(() => {
  const ID='beat-dash';
  const tg=window.Telegram?.WebApp;
  const shell=()=>window.TelePlayGameShell;
  let screen,canvas,renderer,engine,input,startLayer,resultLayer,callbacks={},soundOn=true,deathTimer=0,deathFxRaf=0,runToken=0;
  const $=id=>document.getElementById(id);
  const newRunToken=()=>`${Date.now()}-${Math.random().toString(36).slice(2,9)}`;
  function haptic(type){try{tg?.HapticFeedback?.[type==='success'?'notificationOccurred':'impactOccurred'](type==='success'?'success':type)}catch(_){} }
  function showToast(text,color='#fff'){const el=$('beatEventToast');el.textContent=text;el.style.color=color;el.classList.remove('show');requestAnimationFrame(()=>el.classList.add('show'));clearTimeout(showToast.timer);showToast.timer=setTimeout(()=>el.classList.remove('show'),700)}
  function updateHud(snapshot){if(!snapshot)return;$('beatScore').textContent=Math.floor(snapshot.score).toLocaleString('ru-RU');$('beatProgress').textContent=`${Math.floor(snapshot.progress)}%`;$('beatProgressBar').style.width=`${snapshot.progress}%`;$('beatCombo').textContent=`×${snapshot.combo}`;$('beatComboStat').classList.toggle('hot',snapshot.combo>1);$('beatRunCoins').textContent=snapshot.coins}
  function renderMenuStats(){const stats=shell().getStats(ID);$('beatMenuBest').textContent=`${stats.bestProgress||0}%`;}
  function renderResultProgress(stats){const el=$('beatResultProgress');if(!el)return;el.innerHTML=`<span><b>Лучшее прохождение</b><strong>${stats.bestProgress||0}%</strong></span><i><em style="width:${stats.bestProgress||0}%"></em></i>`}
  function finish(snapshot,reason){
    if(deathTimer)return;deathTimer=setTimeout(()=>{deathTimer=0;const previous=shell().getStats(ID),progress=Math.floor(snapshot.progress),result=shell().saveResult(ID,Math.floor(snapshot.score),{bestProgress:Math.max(previous.bestProgress||0,progress),bestCombo:Math.max(previous.bestCombo||1,snapshot.maxCombo),lastResult:{score:Math.floor(snapshot.score),progress,combo:snapshot.maxCombo,coins:snapshot.coins,reason}}),progressRecord=progress>(previous.bestProgress||0),isRecord=result.newRecord||progressRecord;const reward=snapshot.coins;window.TelePlayCore.RewardManager.award(ID,{coins:reward,score:Math.floor(snapshot.score),metadata:{transactionId:`game:${ID}:run:${runToken}`,runToken}});shell().emit('beat_dash_finished',{gameId:ID,score:Math.floor(snapshot.score),progress,bestProgress:result.bestProgress,bestCombo:result.bestCombo,coins:reward,reason});shell().emit('game_finished',{gameId:ID,score:Math.floor(snapshot.score),reward,maxCombo:snapshot.maxCombo,progress,completed:reason==='complete',playTime:Math.floor(snapshot.elapsed||0)});if(isRecord){screen.classList.add('beat-record');shell().emit('beat_dash_new_record',{gameId:ID,score:Math.floor(snapshot.score),progress});shell().emit('new_record',{gameId:ID,score:Math.floor(snapshot.score)});shell().SoundManager.play('record');haptic('success')}else shell().SoundManager.play('collision');shell().ResultScreen.show(resultLayer,{score:Math.floor(snapshot.score),bestScore:result.bestScore,reward,newRecord:isRecord,title:reason==='complete'?'Уровень пройден!':'Ещё попытка?',details:{progress:`${progress}%`,maxCombo:`×${snapshot.maxCombo}`,runCoins:`${reward} 🪙`}});renderResultProgress(result);resultLayer.hidden=false},reason==='complete'?80:260)}
  function stopDeathFx(){if(deathFxRaf)cancelAnimationFrame(deathFxRaf);deathFxRaf=0}
  function animateDeath(snapshot){stopDeathFx();const until=performance.now()+260;const frame=()=>{renderer.render({...snapshot,state:'dead'});if(performance.now()<until)deathFxRaf=requestAnimationFrame(frame);else deathFxRaf=0};deathFxRaf=requestAnimationFrame(frame)}
  function open(options={}){callbacks=options;screen.hidden=false;startLayer.hidden=false;resultLayer.hidden=true;renderMenuStats();updateHud({score:0,progress:0,combo:1,coins:0});renderer.resize();renderer.render({worldX:0,playerY:0,velocityY:0,elapsed:0,state:'idle'});try{tg?.requestFullscreen();tg?.disableVerticalSwipes()}catch(_){} }
  function start(){if(deathTimer){clearTimeout(deathTimer);deathTimer=0}runToken=newRunToken();stopDeathFx();startLayer.hidden=true;resultLayer.hidden=true;screen.classList.remove('beat-death','beat-record');input?.setEnabled(true);renderer.reset();engine.start();shell().emit('beat_dash_started',{gameId:ID});shell().emit('game_started',{gameId:ID});haptic('light')}
  function restart(){shell().emit('beat_dash_restart',{gameId:ID});start()}
  function hide(){engine.stop();input?.setEnabled(false);stopDeathFx();screen.hidden=true;try{tg?.enableVerticalSwipes();tg?.exitFullscreen()}catch(_){} }
  function close(){hide();callbacks.onHome?.()}
  function init(){
    screen=$('beatDashScreen');canvas=$('beatDashCanvas');startLayer=$('beatStart');resultLayer=$('beatResult');soundOn=shell().SoundManager.enabled();$('beatSound').textContent=soundOn?'🔊':'🔇';renderer=new window.BeatDashRenderer(canvas,window.BeatDashConfig);
    engine=new window.BeatDashEngine(window.BeatDashConfig,{onFrame:snapshot=>{renderer.render(snapshot);updateHud(snapshot)},onJump:action=>{shell().SoundManager.play('jump');haptic('light');if(action.doubleJump)showToast('DOUBLE JUMP','#b993ff')},onJumpSuccess:action=>{showToast(action.kind==='perfect'?'PERFECT +25':'GOOD JUMP +10',action.kind==='perfect'?'#ffd45b':'#62efff');shell().SoundManager.play(action.kind==='perfect'?'perfect':'jump');if(action.kind==='perfect'){shell().emit('beat_dash_perfect_jump',{gameId:ID,combo:action.combo});haptic('medium')}},onCoin:(coin,snapshot)=>{renderer.emit(112*renderer.width/390,renderer.height*.72-coin.y*renderer.width/390,coin.risk==='risk'?'#ff54b7':'#ffd45b',9);shell().SoundManager.play('coin');haptic('light');shell().emit('beat_dash_coin_collected',{gameId:ID,risk:coin.risk,coins:snapshot.coins})},onDeath:({reason,snapshot})=>{screen.classList.add('beat-death');renderer.shake=10;renderer.emit(112*renderer.width/390,renderer.height*.72-snapshot.playerY, '#ff54b7',24);animateDeath(snapshot);shell().emit('beat_dash_death',{gameId:ID,reason,progress:Math.floor(snapshot.progress)});finish(snapshot,reason)},onFinish:snapshot=>finish(snapshot,'complete'),onPause:()=>{$('beatPause').textContent='▶'},onResume:()=>{$('beatPause').textContent='Ⅱ'}});
    $('beatStartButton').addEventListener('click',start);$('beatReplay').addEventListener('click',restart);$('beatClose').addEventListener('click',close);$('beatHome').addEventListener('click',close);
    $('beatPause').addEventListener('click',()=>engine.state==='paused'?engine.resume():engine.pause());$('beatSound').addEventListener('click',()=>{soundOn=!shell().SoundManager.enabled();shell().SoundManager.setEnabled(soundOn);$('beatSound').textContent=soundOn?'🔊':'🔇';$('beatSound').setAttribute('aria-label',soundOn?'Выключить звук':'Включить звук')});
    input=new window.ArcadeInputManager(canvas,{onDown:()=>engine.tap()});input.setEnabled(false);window.addEventListener('resize',()=>renderer.resize());document.addEventListener('visibilitychange',()=>{if(document.hidden&&engine.state==='playing')engine.pause()});renderMenuStats();
  }
  window.BeatDashGame={init,open,close,hide,start,restart,pause:()=>engine?.pause(),resume:()=>engine?.resume(),destroy:()=>engine?.destroy(),getEngine:()=>engine};
  document.readyState==='loading'?document.addEventListener('DOMContentLoaded',init):init();
})();
